def handle(request):
    if request.get("command") == "ping":
        return {"status": "ok", "product": "Meridian Credits"}

    release = request.get("release", "2.0")

    if request.get("command") == "statement":
        lines = request.get("lines", [])

        # Process each line according to the current agreement (release 2.0)
        response_lines = []
        total_credit_cents = 0
        total_amount_due_cents = 0

        # Group lines by account_id and subscription_id for proper processing 
        account_subscription_groups = {}
        for line in lines:
            account_id = line["account_id"]
            subscription_id = line["subscription_id"]
            key = (account_id, subscription_id)

            if key not in account_subscription_groups:
                account_subscription_groups[key] = []
            account_subscription_groups[key].append(line)

        # Process each account/subscription group
        for (_, _), group_lines in account_subscription_groups.items():
            # For each group, we need to assign credits applying the cap rules
            # First calculate uncapped credits (15% of charge_cents) 
            for line in group_lines:
                line["uncapped_credit"] = line["charge_cents"] * 3 // 20  # This is 15% rounded down

            # Sort by charge amount descending, then line_id ascending
            group_lines.sort(key=lambda x: (-x["charge_cents"], x["line_id"]))

            # Apply caps (3000 per account subscription group)
            group_cap = 3000
            remaining_cap = group_cap
            assigned_credits = []

            for line in group_lines:
                credit = min(line["uncapped_credit"], remaining_cap)
                remaining_cap -= credit
                assigned_credits.append(credit)

            # Add to response lines and totals
            for i, line in enumerate(group_lines):
                credit = assigned_credits[i]
                amount_due = max(0, line["charge_cents"] - credit)
                response_lines.append({
                    "line_id": line["line_id"],
                    "credit_cents": credit,
                    "amount_due_cents": amount_due
                })
                total_credit_cents += credit
                total_amount_due_cents += amount_due

        return {
            "release": release,
            "credit_cents": total_credit_cents,
            "amount_due_cents": total_amount_due_cents,
